def apply_edits(text, edits):
    intervals = []
    i = 0
    j = 0
    n = len(text)
    while i < n:
        if j < len(edits) and edits[j][0] == i:
            start, end, repl = edits[j]
            intervals.append((start, end, repl, True))
            i = end
            j += 1
        else:
            nxt = i + 1 if i + 1 < n else None
            if j < len(edits) and (nxt is None or edits[j][0] < nxt):
                start, end, repl = edits[j]
                intervals.append((start, end, repl, True))
                i = end
                j += 1
            else:
                intervals.append((i, i, text[i], False))
                i += 1
    result_parts = []
    for start, end, repl, is_edit in intervals:
        if is_edit:
            result_parts.append(repl)
        else:
            result_parts.append(text[start:end])
    return ''.join(result_parts)
